package com.gregtech.gregtech.registry;
import com.gregtech.gregtech.block.misc.*;import com.gregtech.gregtech.content.logistics.LongDistanceCatalog;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.neoforged.neoforge.registries.DeferredHolder;
public final class GTLongDistance {private GTLongDistance(){}private static final java.util.Map<String,DeferredHolder<Block,Block>> ALL=new java.util.LinkedHashMap<>();public static Block block(String id){return ALL.get(id).get();}public static Block[] transformers(){return ALL.values().stream().map(java.util.function.Supplier::get).filter(b->b instanceof LongDistanceTransformerBlock).toArray(Block[]::new);}
 public static void initialize(){for(var s:LongDistanceCatalog.ALL){var b=GTBlocks.BLOCKS.register(s.id(),()->{var p=BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(s.hardness(),s.resistance()).requiresCorrectToolForDrops();p=p.sound(s.kind().equals("WIRE")?SoundType.WOOL:SoundType.METAL);return switch(s.kind()){case "ITEM_ENDPOINT"->new LongDistEndpointBlock(false,p);case "FLUID_ENDPOINT"->new LongDistEndpointBlock(true,p);case "TRANSFORMER"->new LongDistanceTransformerBlock(s.voltage(),p);default->new LongDistPipeBlock(s,p);};});ALL.put(s.id(),b);GTBlocks.BLOCK_ITEMS.register(s.id(),()->new com.gregtech.gregtech.item.LongDistanceBlockItem(b.get(),new net.minecraft.world.item.Item.Properties().stacksTo(s.stackLimit()),s));}}
}
